package dev.classityreal.pext.locked

import java.security.MessageDigest

/**
 * HARD-LOCKED. Do not edit this file.
 *
 * This app extracts .pac contents to storage. It does not unlock bootloaders
 * and it does not flash partitions. The payload and hash below are the
 * configuration. If they disagree, extraction stays off unless the user
 * turns on Experimental in Settings, and even then only the allow-list runs.
 */
object LockedConfig {
    const val PAYLOAD =
        "copy-in|list|extract|copy-out|engines=unpac,pacextractor|flags=-d|no-flash=1"

    const val SHA256 = "a2a0c4dd01bf801a73009530d12e1cb929fb8a6b94ad60dc6cb21b31f1e5b34a"

    val allowedSteps: Set<String> = setOf("copy-in", "list", "extract", "copy-out")

    fun integrityOk(): Boolean = sha256(PAYLOAD) == SHA256

    fun isSafePartitionName(name: String): Boolean {
        if (name.isBlank() || name.length > 128) return false
        if (name.startsWith("-") || name.contains("..")) return false
        if (name.any { ch ->
                ch == '/' || ch == '\\' || ch.isWhitespace() || ch == ';' || ch == '|' || ch == '&' || ch == '\u0000'
            }
        ) return false
        return true
    }

    fun assertSteps(steps: List<String>) {
        val blocked = steps.filter { it !in allowedSteps }
        if (blocked.isNotEmpty()) {
            throw IllegalStateException(
                "Blocked step(s): ${blocked.joinToString()}. This app does not flash, erase, or unlock."
            )
        }
    }

    private fun sha256(value: String): String {
        val digest = MessageDigest.getInstance("SHA-256").digest(value.toByteArray(Charsets.UTF_8))
        return digest.joinToString("") { "%02x".format(it) }
    }
}
